<script module lang="ts">
/**
 * Modal interruption of the page (`design/components/dialog.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dialog.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext, onDestroy, setContext, type Snippet } from 'svelte'

import * as zag from '@zag-js/dialog'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  SlotOutlet,
  SlotScope,
  agentMember,
  attributes,
  focusPlace,
  focusReturnTarget,
  joinSlot,
  modalFocusTarget,
  normalizeProps,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/dialog.module.css'
import Button from '../controls/Button.svelte'

export interface DialogProps {
  /**
   * Uses `alertdialog` rather than `dialog`, for an interruption the reader must answer.
   * ConfirmDialog sets it for its danger tone.
   */
  alert?: boolean
  children?: Snippet
  closeLabel?: string
  defaultOpen?: boolean
  description?: string
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  dismissible?: boolean
  /**
   * Actions. One primary (`solid`), rightmost; dismiss is outline or ghost.
   */
  footer?: Snippet
  /**
   * Which footer control has focus on open; `dismiss` suits a panel that asks whether you meant
   * it (see `initialFocus`).
   */
  initialFocus?: 'primary' | 'dismiss'
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * `'auto'` is the card, and the whole screen below `30rem` (the overlay class's viewport
   * exemption). `'sheet'` keeps the card above `30rem` and becomes a bottom sheet below it (the
   * sheet presentation, `design/components/README.md`). It is for content-light confirm and pick
   * dialogs, where a full-screen takeover is too heavy. Only the shape changes: scrim, trap,
   * `dismissible`, initial focus and return focus are Dialog's in both forms, which is why it
   * can be a prop.
   */
  presentation?: 'auto' | 'sheet'
  size?: 'sm' | 'md' | 'lg'
  title: string
  /**
   * A governed control, usually a Button, cloned to receive `onClick`, which also tells the
   * panel where it was opened from.
   */
  trigger?: Snippet
}
</script>

<script lang="ts">
let {
  alert = false,
  children,
  closeLabel = 'Close',
  defaultOpen,
  description,
  dismissible = true,
  footer,
  initialFocus = 'primary',
  onOpenChange,
  open,
  presentation = 'auto',
  size = 'md',
  title,
  trigger,
}: DialogProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ size: size }))
const lent = getContext<string | undefined>('polymorph:identity')
const lender = getContext<{ element?: () => Element | null | undefined } | undefined>(
  'polymorph:borrowed',
)
setContext('polymorph:borrowed', undefined)
const slots = {
  get default() {
    return children
  },
  get footer() {
    return footer
  },
  get trigger() {
    return trigger
  },
}
let pressed = $state(null as HTMLElement | null)
let returnTo = $state(null as ReturnType<typeof focusPlace>)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheet = $derived(presentation === 'sheet' && phone.current)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      defaultOpen: defaultOpen,
      role: alert ? 'alertdialog' : 'dialog',
      closeOnEscape: dismissible,
      closeOnInteractOutside: dismissible,
      initialFocusEl: () => modalFocusTarget(panel, initialFocus),
      finalFocusEl: () => focusReturnTarget(returnTo, [panel]),
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const openFrom = $derived((event?: Event) => {
  if (event?.currentTarget instanceof HTMLElement) pressed = event.currentTarget
  api.setOpen(true)
})
const scrimPresent = usePresence(
  () => api.open,
  () => scrim,
  'dialog.scrim',
)
const panelPresent = usePresence(
  () => api.open,
  () => panel,
  () => (sheet ? 'sheet.panel' : 'dialog.panel'),
  { sheetSide: 'bottom' },
)
const triggerScope: SlotScope = new SlotScope({
  pass: (): Record<string, unknown> => ({ onClick: openFrom }),
})
const effect1 = () => {
  lender && (lender.element = () => panel)
}
watchEffect(effect1)
const effect2 = () => {
  api.open && ((returnTo = focusPlace(pressed ?? document.activeElement)), (pressed = null))
}
watchEffect(effect2, { watch: () => api.open })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = lender
    ? () => {}
    : agentMember({
        member: 'Dialog',
        element: () => panel,
        state: () => ({ open: api.open }),
        actions: {
          close: () =>
            (() => {
              if (!dismissible)
                throw new Error('The dialog asks for a choice among its own actions.')
              api.setOpen(false)
            })(),
        },
      })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<SlotOutlet scope={triggerScope} snippet={trigger}
  /><Portal
    >{#if scrimPresent.current
      }<div
        bind:this={scrim}
        {...attributes(api.getBackdropProps())}
        class={styles.scrim}
        hidden={undefined}
      ></div
    >{/if
    }{#if panelPresent.current
      }<div
        {...attributes(api.getPositionerProps())}
        class={[sheet ? styles.sheetPositioner : undefined, !sheet ? styles.positioner : undefined]}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={[sheet ? styles.sheetPanel : undefined, !sheet ? styles.panel : undefined]}
          hidden={undefined}
          data-presentation={sheet ? 'sheet' : undefined}
          data-size={size}
          data-member={lent ?? 'dialog'}
          ><h2 {...attributes(api.getTitleProps())} class={styles.title}>{title}</h2
          >{#if description !== undefined
            }<p {...attributes(api.getDescriptionProps())} class={styles.description}
              >{description
            }</p
          >{/if
          }<div class={styles.body} data-dialog-part="body">{@render children?.()}</div
          >{#if slots.footer
            }<div class={styles.footer} data-dialog-part="footer">{@render footer?.()}</div
          >{/if
          }{#if dismissible
            }<div class={styles.close} data-dialog-part="close"
              ><Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="close"
                label={closeLabel}
                onClick={() => { api.setOpen(false) }}
            /></div
          >{/if
        }</div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
